import express from 'express';import dotenv from 'dotenv';import fs from 'node:fs';dotenv.config();const app=express();app.use(express.json());const PORT=Number(process.env.SUBSTACK_BRIDGE_PORT||7194);app.get('/health',(_q,r)=>r.json({ok:true,service:'substack-bridge',publication:process.env.SUBSTACK_PUBLICATION_URL||''}));app.post('/draft',(q,r)=>{const root=process.env.DATA_ROOT||'/var/lib/exosys-hub';fs.mkdirSync(root+'/drafts',{recursive:true});const p=root+'/drafts/substack-'+Date.now()+'.md';fs.writeFileSync(p,q.body.markdown||'# Draft\n');r.json({ok:true,draft:p})});app.listen(PORT,'0.0.0.0',()=>console.log('substack bridge',PORT));